namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int RatingCount { get; set; }
    public int RatingTotal { get; set; }

    public double AverageRating => RatingCount == 0 ? 0 : (double)RatingTotal / RatingCount;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast, Yogurt, Garam masala, Cumin, Tomato sauce, Heavy cream, Garlic, Ginger, Onion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Stir in cream and cooked chicken.\n6. Serve over basmati rice."
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheddar cheese, Sour cream, Salsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with meat and toppings.\n5. Serve with salsa and sour cream."
        },
        new Recipe
        {
            Id = 4, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Green onions, Peanuts, Tamarind paste, Fish sauce, Lime",
            Steps = "1. Soak rice noodles in warm water 30 min.\n2. Stir-fry shrimp until pink, set aside.\n3. Scramble eggs in the wok.\n4. Add noodles, tamarind sauce, and fish sauce.\n5. Toss with shrimp, bean sprouts, and green onions.\n6. Serve with crushed peanuts and lime wedge."
        },
        new Recipe
        {
            Id = 5, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale off heat.\n5. Quickly stir in egg mixture to create creamy sauce.\n6. Serve immediately with extra pecorino."
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Preheat oven to 425°F. Butter ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla.\n4. Fold chocolate mixture into eggs, then add flour.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately."
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Green curry paste, Coconut milk, Chicken thighs, Thai basil, Bamboo shoots, Bell pepper, Fish sauce, Sugar",
            Steps = "1. Heat curry paste in a pot until fragrant.\n2. Add half the coconut milk and stir.\n3. Add sliced chicken, cook 5 minutes.\n4. Pour in remaining coconut milk, bamboo shoots, peppers.\n5. Season with fish sauce and sugar.\n6. Garnish with Thai basil, serve with jasmine rice."
        },
        new Recipe
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt",
            Steps = "1. Halve and pit avocados, scoop into bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, and jalapeño.\n4. Add lime juice, cilantro, and salt.\n5. Taste and adjust seasoning.\n6. Serve with tortilla chips."
        }
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.RatingCount++;
            recipe.RatingTotal += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

