@page "/"

<PageTitle>Recipe Community</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@category</h5>
                    <p class="card-text">Browse our collection of @category recipes.</p>
                    <a href="categories/@category" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/categories"
@page "/categories/{CategoryName}"

<PageTitle>Browse Recipes - @(CategoryName ?? "All Categories")</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>📂 Recipe Categories</h1>
    <div class="list-group mt-3">
        @foreach (var category in Categories)
        {
            <a href="categories/@category" class="list-group-item list-group-item-action">
                @category
            </a>
        }
    </div>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <div class="list-group mt-3">
        @foreach (var recipe in Recipes)
        {
            <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action">
                <h5 class="mb-1">@recipe.Title</h5>
                <small class="text-muted">
                    @if (recipe.RatingCount > 0)
                    {
                        <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet</span>
                    }
                </small>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string? CategoryName { get; set; }
    [Inject] public RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];
    private IReadOnlyList<RecipeCommunity.Models.Recipe> Recipes = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
        if (!string.IsNullOrEmpty(CategoryName))
        {
            Recipes = RecipeService.GetByCategory(CategoryName);
        }
    }
}

