@page "/"

<PageTitle>Recipe Community</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@category</h5>
                    <p class="card-text">Browse our collection of @category recipes.</p>
                    <a href="categories/@category" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

